-- Fiche Politesse et consignes (CM1) - anglais, notion 'en_politesse_consignes'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm1', 'english', 'Politesse et consignes', $fiche$
[titre]Interdire poliment[/titre]
[cadre]ne cours pas = [b]Don't[/b] run · ne touche pas = [b]Don't[/b] touch[/cadre]
[cadre=astuce]Pour interdire : [b]Don't[/b] + verbe. Et toujours : please, thank you, sorry.[/cadre]
[page]
[titre]Les mots à connaître (1)[/titre]
[center][font_size=22][b][color=#classe]Être poli[/color][/b][/font_size][/center]
